<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../repositories/userPDO.php';require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);requireRole($user,['Administrator']);$search=trim((string)($_GET['search']??''));$role=(string)($_GET['role']??'');$status=(string)($_GET['status']??'');if($role!==''&&!in_array($role,['Student','Tutor','Administrator'],true))$role='';if($status!==''&&!in_array($status,['Active','Inactive'],true))$status='';$rows=searchUsers($pdo,$search,$role,$status);require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Manage users</h1><form method="get" class="row g-2 mb-3"><div class="col"><input class="form-control" name="search" placeholder="Search name or email" value="<?=htmlspecialchars($search,ENT_QUOTES,'UTF-8')?>"></div><div class="col"><select class="form-select" name="role"><option value="">All roles</option><?php foreach(['Student','Tutor','Administrator'] as $v):?><option <?=$v===$role?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Active','Inactive'] as $v):?><option <?=$v===$status?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary">Search</button></div></form><?php if(!$rows):?><p>No matching accounts.</p><?php else:?><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['email'],ENT_QUOTES,'UTF-8')?></td><td><?=$r['role']?></td><td><?=$r['status']?></td><td><a href="user-details.php?user_id=<?=(int)$r['user_id']?>">Manage</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></main><?php require __DIR__.'/../includes/footer.php';?>
